function dialogKey(event:KeyboardEvent, close:()=>void, busy:boolean){
  if(event.key==='Escape'){event.preventDefault();event.stopPropagation();if(!busy)close();return}
  if(event.key!=='Tab')return
  const panel=event.currentTarget as HTMLElement
  const nodes=[...panel.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),select:not(:disabled),[tabindex="0"]')].filter(node=>node.getClientRects().length)
  const first=nodes[0],last=nodes.at(-1)
  if(!first){event.preventDefault();panel.focus({preventScroll:true});return}
  if(!panel.contains(document.activeElement)||document.activeElement===panel){event.preventDefault();(event.shiftKey?last:first)?.focus()}
  else if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}
  else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}
}
