function matchesFilter(task:TaskEntity,target=filter.value,ignoreCompletion=false){
  if(ignoreCompletion)task={...task,completed:false}
  const now=new Date()
  const due=dateValue(effectiveDate(task)),todayStart=new Date();todayStart.setHours(0,0,0,0)
  if(task.abandonedAt)return target==='abandoned'||target==='all'
  if(target==='today'||target==='next7')return matchesTaskScheduleFilter(task,target)
  if(target==='open')return !task.completed&&!task.abandonedAt
  if(target==='done')return task.completed
  if(target==='abandoned')return Boolean(task.abandonedAt)
  if(target==='priority')return !task.completed&&task.priority>=2
  if(target==='soon')return Boolean(!task.completed&&due&&due>=now&&due.getTime()-now.getTime()<=3*86400000)
  if(target==='overdue')return taskBucket(task)==='overdue'
  if(target==='nodate')return !task.completed&&!due
  if(target==='scheduled')return !task.completed&&Boolean(due)
  if(target==='recurring')return !task.completed&&Boolean(task.recurrenceRule)
  if(target==='inbox')return !task.taskListId&&!task.completed&&!task.abandonedAt
  if(target.startsWith('list:'))return task.taskListId===Number(target.slice(5))&&!task.completed&&!task.abandonedAt
  if(target.startsWith('project:'))return task.projectUid===target.slice(8)
  return true
}
const filterCounts=computed(()=>{
  const counts=new Map<string,number>()
  const filters=['today','next7','open','done','abandoned','priority','soon','overdue','nodate','scheduled','recurring','inbox','all']
  for(const task of currentRecurringTasks(store.tasks).filter(task=>scopedTaskUids.value.has(task.uid))){
    if(pendingDeleteUids.value.has(task.uid)||task.parentTaskUid)continue
    for(const target of filters)if(matchesFilter(task,target))counts.set(target,(counts.get(target)||0)+1)
    if(task.taskListId&&!task.completed&&!task.abandonedAt){const key=`list:${task.taskListId}`;counts.set(key,(counts.get(key)||0)+1)}
    if(task.projectUid){const key=`project:${task.projectUid}`;counts.set(key,(counts.get(key)||0)+1)}
  }
  return counts
})
