})
type TaskListRow={kind:'heading';key:string;label:string;count:number;overdue?:boolean;processed?:boolean}|{kind:'task';key:string;task:TaskEntity}
const taskListRows=computed<TaskListRow[]>(()=>{
 const groups=[['overdue','已逾期'],['today','今天'],['next7','未来 7 天'],['calendar','以后'],['inbox','无日期'],['completed','已完成'],['abandoned','已放弃']]
 const rows:TaskListRow[]=[]
 for(const [bucket,label] of groups){const tasks=filteredTasks.value.filter(task=>taskBucket(task)===bucket);if(!tasks.length)continue;const key=`heading-${bucket}`;rows.push({kind:'heading',key,label,count:tasks.length,overdue:bucket==='overdue'});if(!collapsedTaskGroups.value.has(key))rows.push(...tasks.map(task=>({kind:'task' as const,key:task.uid,task})))}
 if(listScopeActive.value&&processedListTasks.value.length){rows.push({kind:'heading',key:'heading-processed',label:'已处理',count:processedListTasks.value.length,processed:true});if(processedExpanded.value)rows.push(...processedListTasks.value.map(task=>({kind:'task' as const,key:`processed-${task.uid}`,task})))}
 return rows
})

