  saved=await store.update({...task,...fields,title:changes.title.trim(),startAt:changes.startAt?changes.startAt.replace('T',' '):null,dueAt:changes.dueAt?changes.dueAt.replace('T',' '):null,estimatedMinutes:changes.estimatedMinutes?Number(changes.estimatedMinutes):null,...(changes.completed!==task.completed?{completedAt:changes.completed?new Date().toISOString():null}:{})} as TaskEntity)
