async function executeTaskBulk(){if(bulkBusy.value)return;const items=[...bulkItems.value];if(!items.length||!bulkAction.value)return;const action=bulkAction.value,targetProject=projects.value.find(item=>item.uid===bulkProjectUid.value),targetArea=targetProject?.areaUid||bulkAreaUid.value;const targetList=taskLists.value.find(item=>item.uid===bulkTaskListUid.value);if(action==='move'&&((bulkDestination.value==='list'&&!targetList)||(bulkDestination.value==='project'&&!targetArea))){bulkFailures.value=[{item:items[0],message:bulkDestination.value==='list'?'请选择目标清单':'请选择目标领域'}];return}if(action==='tag'&&!bulkTagId.value){bulkFailures.value=[{item:items[0],message:'请选择标签'}];return}bulkBusy.value=true;bulkFailures.value=[];bulkCompleted.value=0;const result=await runBulkOperation(items,async task=>{if(action==='complete'){await completeTask(task,true);return task}if(action==='tag')return store.organize(task,[...new Set([...(task.tagIds||[]),bulkTagId.value!])]);if(action==='date')return store.update({...task,startAt:bulkDate.value?bulkDate.value.replace('T',' '):null});if(action==='priority')return store.update({...task,priority:bulkPriority.value});if(action==='delete'){await store.remove(task);return task}if(action==='copy')return store.create({...task,id:undefined,uid:undefined,title:`${task.title} - 副本`,recurrenceSourceUid:null,recurrenceOccurrenceKey:null,abandonedAt:null,parentTaskUid:null,completed:false,completedAt:null,version:undefined} as Partial<TaskEntity>);return store.update({...task,...taskLocation(bulkDestination.value==='list'?{kind:'list',list:targetList!}:bulkDestination.value==='project'?{kind:'project',project:targetProject||null,areaUid:targetArea}:{kind:'inbox'})})},{chunkSize:20,onProgress:done=>bulkCompleted.value=done});bulkFailures.value=result.failed;if(!['delete','copy'].includes(action)){for(const value of result.succeeded)if(!bulkBatchOriginals.has(value.item.uid))bulkBatchOriginals.set(value.item.uid,value.item);if(bulkBatchOriginals.size)bulkUndo.value={action,items:[...bulkBatchOriginals.values()]}};bulkBusy.value=false;selected.value=new Set(result.failed.map(value=>value.item.uid));if(!result.failed.length)bulkAction.value=undefined;else{await nextTick();bulkPanel.value?.focus({preventScroll:true})}}
async function undoTaskBulk(){const undo=bulkUndo.value;if(!undo||bulkBusy.value)return;bulkBusy.value=true;bulkUndoFailures.value=[];bulkFailures.value=[];bulkCompleted.value=0;const result=await runBulkOperation(undo.items,async original=>{const current=store.tasks.find(item=>item.uid===original.uid);if(!current)throw new Error('任务已不存在');if(undo.action==='complete'){await store.complete(current,original.completed);return current}if(undo.action==='tag')return store.organize(current,original.tagIds||[]);if(undo.action==='date')return store.update({...current,startAt:original.startAt||null});if(undo.action==='priority')return store.update({...current,priority:original.priority});return store.update({...current,areaUid:original.areaUid||null,projectUid:original.projectUid||null,taskListId:original.taskListId||null,taskListUid:original.taskListUid||null,listName:original.listName})},{chunkSize:20,onProgress:done=>bulkCompleted.value=done});bulkFailures.value=result.failed;bulkUndoFailures.value=result.failed;bulkBusy.value=false;bulkUndo.value=result.failed.length?{...undo,items:result.failed.map(value=>value.item)}:undefined}
async function toggleTagImmediately(id:number){const task=selectedTask.value;if(!task||detailSaving.value)return;const values=new Set(task.tagIds||[]);values.has(id)?values.delete(id):values.add(id);detailSaving.value=true;detailError.value='';try{const saved=await store.organize(task,[...values]);fieldDraft.value={...fieldDraft.value,tagIds:[...(saved.tagIds||[])]}}catch(source){detailError.value=source instanceof Error?source.message:'标签保存失败'}finally{detailSaving.value=false}}
async function createDetailTag(){const name=tagQuery.value.trim();if(!name||detailSaving.value)return;const existing=tags.value.find(item=>item.name.toLowerCase()===name.toLowerCase());if(existing){await toggleTagImmediately(existing.id);return}detailSaving.value=true;detailError.value='';try{const created=await tagsService.create(name);tags.value.push(created);const task=selectedTask.value;if(task){const saved=await store.organize(task,[...new Set([...(task.tagIds||[]),created.id])]);fieldDraft.value={...fieldDraft.value,tagIds:[...(saved.tagIds||[])]}}tagQuery.value=''}catch(source){detailError.value=source instanceof Error?source.message:'标签创建失败'}finally{detailSaving.value=false}}
function localDateTime(date:Date,time='18:00'){return`${dayKey(date)}T${time}`}
async function chooseTaskDate(kind:'today'|'tomorrow'|'friday'|'monday'){const value=new Date();if(kind==='tomorrow')value.setDate(value.getDate()+1);if(kind==='friday'){const distance=(5-value.getDay()+7)%7;value.setDate(value.getDate()+(distance||7))}if(kind==='monday'){const distance=(1-value.getDay()+7)%7;value.setDate(value.getDate()+(distance||7))}const target=detailField.value==='time'?timeTarget.value:detailField.value==='date'?'date':'due',key=target==='date'?'startAt':'dueAt';await saveField({[key]:localDateTime(value,target==='date'?'09:00':'18:00')})}
async function saveCustomTaskDate(){const target=detailField.value==='time'?timeTarget.value:detailField.value==='date'?'date':'due',key=target==='date'?'startAt':'dueAt';if(!deadlineDate.value){await saveField({[key]:null});return}await saveField({[key]:`${deadlineDate.value}T${deadlineTime.value||(target==='date'?'09:00':'18:00')}`})}
async function saveDuration(){const minutes=Math.round(Number(durationMinutes.value));if(minutes<1||minutes>10080){detailError.value='预计时长必须在 1 分钟到 7 天之间';return}await saveField({estimatedMinutes:minutes})}
async function saveReminder(values:number[]){const task=selectedTask.value;if(!task||detailSaving.value)return;if(!task.startAt&&!task.dueAt){detailError.value='请先设置任务日期或截止时间';return}detailSaving.value=true;detailError.value='';try{const saved=await store.update({...task,reminderOffsetsMinutes:[...new Set(values)].sort((a,b)=>a-b)});fieldDraft.value={...fieldDraft.value,...saved,reminderOffsetsMinutes:[...(saved.reminderOffsetsMinutes||[])]}}catch(source){detailError.value=source instanceof Error?source.message:'提醒保存失败'}finally{detailSaving.value=false}}
