async function addCustomReminder(){const minutes=Math.round(Number(reminderAmount.value)*Number(reminderUnit.value));if(minutes<1||minutes>525600){detailError.value='提醒时间必须在 1 分钟到 365 天之间';return}await saveReminder([...(selectedTask.value?.reminderOffsetsMinutes||[]),minutes])}
function detailEscape(event:KeyboardEvent){if(event.defaultPrevented||event.key!=='Escape'||selectedTask.value)return;if(taskViewMenu()?.open)closeTaskViewMenu();else if(detailMoreOpen.value)detailMoreOpen.value=false;else if(detailField.value)cancelField()}
function detailMoreOutside(event:PointerEvent){const target=event.target as Node|null,menu=taskViewMenu();if(menu?.open&&target&&!menu.contains(target))closeTaskViewMenu();if(detailMoreOpen.value&&!(event.target as HTMLElement|null)?.closest('.task-detail-more'))detailMoreOpen.value=false}
