async function moveBoard(task:TaskEntity,state:BoardState){if(state==='done'){await completeTask(task,true);return}if(task.completed)await completeTask(task,false);const current=store.tasks.find(item=>item.uid===task.uid)||task;await store.update({...current,completed:false,startAt:state==='doing'?(current.startAt||new Date().toISOString().slice(0,19).replace('T',' ')):null})}
