async function scheduleTask(task:TaskEntity,dateKeyValue:string|null){const current=store.tasks.find(item=>item.uid===task.uid)||task;if(!dateKeyValue){await store.update({...current,startAt:null,dueAt:null});return}const existing=dateValue(current.startAt),time=existing?`${String(existing.getHours()).padStart(2,'0')}:${String(existing.getMinutes()).padStart(2,'0')}`:'09:00';await store.update({...current,startAt:`${dateKeyValue} ${time}:00`})}
function dropOnDate(event:DragEvent,dateKeyValue:string|null){const uid=event.dataTransfer?.getData('text/task-uid')||draggingTaskUid.value,task=store.tasks.find(item=>item.uid===uid);draggingTaskUid.value='';if(task)void scheduleTask(task,dateKeyValue)}
function changeMonth(offset:number){calendarAnchor.value=new Date(calendarAnchor.value.getFullYear(),calendarAnchor.value.getMonth()+offset,1);selectedCalendarDay.value=dayKey(calendarAnchor.value)}
function openFocusRecords(task:TaskEntity){router.push({path:'/focus',query:{taskUid:task.uid,title:task.title,from:'/tasks'}})}
function scheduleDelete(items:TaskEntity[]){const queued=new Set(items.map(item=>item.uid));deleteFailures.value=deleteFailures.value.filter(failure=>!queued.has(failure.item.uid));const existing=pendingDelete.value?.items||[],values=[...new Map([...existing,...items].map(item=>[item.uid,item])).values()];if(pendingDelete.value)window.clearTimeout(pendingDelete.value.timer);const timer=window.setTimeout(()=>void finalizeDelete(),5000);pendingDelete.value={items:values,timer}}
async function finalizeDelete(){const entry=pendingDelete.value;if(!entry)return;window.clearTimeout(entry.timer);pendingDelete.value=null;const result=await runBulkOperation(entry.items,async task=>{await store.remove(task);return task},{chunkSize:20});const attempted=new Set(entry.items.map(item=>item.uid));deleteFailures.value=[...deleteFailures.value.filter(failure=>!attempted.has(failure.item.uid)),...result.failed]}
function undoDelete(){if(!pendingDelete.value)return;window.clearTimeout(pendingDelete.value.timer);pendingDelete.value=null}
