function notePickerContext(note:{projectUid?:string|null;areaUid?:string|null;updatedAt?:string;createdAt?:string}){const project=projects.value.find(item=>item.uid===note.projectUid),area=areas.value.find(item=>item.uid===note.areaUid),date=note.updatedAt||note.createdAt;return[project?.name||area?.name,date?new Date(date).toLocaleDateString('zh-CN'):null].filter(Boolean).join(' · ')||'未分类'}
