async function stopRecurrence(task:TaskEntity){await store.update({...task,recurrenceRule:null})}
async function abandonTask(task:TaskEntity){await store.update({...task,completed:false,completedAt:null,abandonedAt:new Date().toISOString(),recurrenceRule:task.recurrenceRule||null})}
async function restoreTask(task:TaskEntity){await store.update({...task,completed:false,completedAt:null,abandonedAt:null})}
function shiftDate(value:string|null|undefined,days:number){if(!value)return null;const date=dateValue(value);if(!date)return value||null;date.setDate(date.getDate()+days);const part=(number:number)=>String(number).padStart(2,'0');return`${date.getFullYear()}-${part(date.getMonth()+1)}-${part(date.getDate())} ${part(date.getHours())}:${part(date.getMinutes())}:${part(date.getSeconds())}`}
async function postponeTask(task:TaskEntity,target:'today'|'tomorrow'|'week'){const anchor=dateValue(effectiveDate(task));if(!anchor)return;const destination=new Date();destination.setHours(0,0,0,0);if(target==='tomorrow')destination.setDate(destination.getDate()+1);if(target==='week')destination.setDate(destination.getDate()+7);const source=new Date(anchor);source.setHours(0,0,0,0);const days=Math.round((destination.getTime()-source.getTime())/86400000);await store.update({...task,startAt:shiftDate(task.startAt,days),dueAt:shiftDate(task.dueAt,days)})}
async function postponeAllOverdue(){const todayStart=new Date();todayStart.setHours(0,0,0,0);const overdue=filteredTasks.value.filter(task=>!task.completed&&!task.abandonedAt&&Boolean(effectiveDate(task))&&dateValue(effectiveDate(task))!<todayStart);if(!overdue.length||!await confirmDialog({title:'全部顺延到今天？',message:`将修改当前视图中 ${overdue.length} 个逾期任务的计划和截止日期，原逾期日期将被替换。`,confirmText:'确认顺延',tone:'warning'}))return;for(const task of overdue)await postponeTask(task,'today')}
function postponeMenu(task:TaskEntity,event:MouseEvent){openContextMenu(event,[{id:'today',label:'顺延到今天',icon:'◷',run:()=>postponeTask(task,'today')},{id:'tomorrow',label:'顺延到明天',icon:'→',run:()=>postponeTask(task,'tomorrow')},{id:'week',label:'顺延一周',icon:'»',run:()=>postponeTask(task,'week')}])}
function taskContextMenu(task:TaskEntity,event:MouseEvent){const overdue=!task.completed&&!task.abandonedAt&&Boolean(effectiveDate(task)&&dateValue(effectiveDate(task))!<new Date(new Date().setHours(0,0,0,0)));openContextMenu(event,[...(overdue?[{id:'today',label:'顺延到今天',icon:'◷',run:()=>postponeTask(task,'today')},{id:'tomorrow',label:'顺延到明天',icon:'→',run:()=>postponeTask(task,'tomorrow')},{id:'week',label:'顺延一周',icon:'»',run:()=>postponeTask(task,'week')}]:[]),...(task.recurrenceRule?[{id:'stop-recurrence',label:'停止重复',icon:'↻',run:()=>stopRecurrence(task)}]:[]),task.abandonedAt?{id:'restore',label:'恢复为未完成',icon:'↺',run:()=>restoreTask(task)}:{id:'abandon',label:task.recurrenceRule?'跳过此周期':'放弃任务',icon:'⊘',danger:true,separator:overdue,run:()=>abandonTask(task)}])}
async function submitTextDialog(){const dialog=textDialog.value,value=dialog?.value.trim();if(!dialog||!value||textDialogBusy.value)return;textDialogBusy.value=true;textDialogError.value='';try{if(dialog.mode==='subtask'){const parent=selectedTask.value;if(!parent)return;await store.create({title:value,description:'',parentTaskUid:parent.uid,areaUid:parent.areaUid||null,projectUid:parent.projectUid||null,taskListId:parent.taskListId||null,taskListUid:parent.taskListUid||null,listName:parent.listName||'收集箱',priority:0,completed:false,sortOrder:selectedChildren.value.length});detailTab.value='details'}else if(dialog.mode==='create-list')taskLists.value.push(await taskListsService.create(value,taskLists.value.length));else if(activeTaskList.value&&value!==activeTaskList.value.name){const saved=await taskListsService.update(activeTaskList.value,{name:value}),index=taskLists.value.findIndex(item=>item.id===saved.id);taskLists.value[index]=saved;await store.load()}taskListError.value=taskListsService.cacheError();textDialog.value=null}catch(source){textDialogError.value=source instanceof Error?source.message:'保存失败'}finally{textDialogBusy.value=false;if(textDialog.value){await nextTick();textPanel.value?.focus({preventScroll:true})}}}
async function deleteTaskList(){const list=activeTaskList.value;if(!list)return;const tasks=store.tasks.filter(task=>task.taskListId===list.id);const prompt=tasks.length?`清单中有 ${tasks.length} 个任务。将它们移动到收集箱后删除清单？`:`删除清单“${list.name}”？`;if(!await confirmDialog(prompt))return;taskListError.value='';try{for(const task of tasks)await store.update({...task,taskListId:null,taskListUid:null,listName:'收集箱'});await taskListsService.remove(list);taskLists.value=taskLists.value.filter(item=>item.id!==list.id);filter.value='inbox';taskListError.value=taskListsService.cacheError()}catch(source){taskListError.value=source instanceof Error?source.message:'删除清单失败'}}
async function moveTaskList(offset:number){const list=activeTaskList.value;if(!list)return;const ordered=sortedTaskLists.value;const index=ordered.findIndex(item=>item.id===list.id),other=ordered[index+offset];if(!other)return;taskListError.value='';try{const first=await taskListsService.update(list,{sortOrder:other.sortOrder??index+offset});const second=await taskListsService.update(other,{sortOrder:list.sortOrder??index});taskLists.value=taskLists.value.map(item=>item.id===first.id?first:item.id===second.id?second:item)}catch(source){taskListError.value=source instanceof Error?source.message:'调整清单顺序失败'}}
function acceptBackgroundTasks(event:Event){void refreshTaskLists();const values=(event as CustomEvent<TaskEntity[]>).detail;if(Array.isArray(values))store.acceptBackgroundRefresh(values)}
let disposed=false,listsRefresh:Promise<void>|undefined
function refreshTaskLists(){
  if(listsRefresh)return listsRefresh
  const scope=taskDataScope()
  listsRefresh=taskListsService.list().then(values=>{if(!disposed&&scope===taskDataScope()){taskLists.value=values;taskListError.value=taskListsService.cacheError()}}).catch(()=>{if(!disposed&&scope===taskDataScope())taskListError.value='清单暂时无法更新，已保留缓存'}).finally(()=>{listsRefresh=undefined})
  return listsRefresh
}
watch(()=>[route.query.task,route.query.activation],async ([uid])=>{
 if(props.detailsOnly||route.query.source!=='reminder'||typeof uid!=='string')return
 await store.load({force:true});if(disposed||route.query.task!==uid)return
 const task=store.tasks.find(item=>item.uid===uid);if(task){reminderTaskUid.value=uid;editTask(task)}
},{flush:'post'})
onMounted(async()=>{
  window.addEventListener('beforeunload',protectTaskPageExit)
  window.addEventListener('keydown',detailEscape);window.addEventListener('pointerdown',detailMoreOutside);window.addEventListener(TASKS_BACKGROUND_REFRESH_EVENT,acceptBackgroundTasks);window.addEventListener('online',refreshTaskLists)
  const requestedTask=props.detailTaskUid||(typeof route.query.task==='string'?route.query.task:'')
  const requestedFromReminder=!props.detailsOnly&&route.query.source==='reminder'
  if(typeof route.query.filter==='string')filter.value=route.query.filter
  // 项目列表可独立创建或完成任务，详情打开时重读，避免沿用任务工作台的旧缓存。
  void store.load({force:Boolean(props.detailsOnly)||requestedFromReminder}).then(()=>{if(!disposed&&requestedTask){const task=(requestedFromReminder?store.tasks:scopedTasks.value).find(item=>item.uid===requestedTask);if(task){if(requestedFromReminder)reminderTaskUid.value=requestedTask;editTask(task);if(props.detailsOnly)emit('detail-ready')}else if(props.detailsOnly){emit('detail-error',store.error||'任务已不存在或不属于当前项目');emit('detail-close')}}}).catch(()=>{if(!disposed&&props.detailsOnly){emit('detail-error','任务详情加载失败，请重试');emit('detail-close')}})
  try{taskLists.value=await taskListsService.loadCached()}catch{taskLists.value=taskListsService.cached();taskListError.value='本机任务清单读取失败，请重试'}
  if(disposed)return
  void refreshTaskLists()
  void workspaceService.areas().then(values=>areas.value=values).catch(()=>undefined)
  void workspaceService.projects(undefined,true).then(values=>projects.value=values.filter(item=>!globalAreaUid.value||item.areaUid===globalAreaUid.value||item.uid===projectScopeUid.value)).catch(()=>undefined)
  void tagsService.list().then(values=>tags.value=values).catch(()=>undefined)
  if(!props.detailsOnly&&!requestedFromReminder&&(route.query.filter||route.query.task))void router.replace('/tasks')
})
onBeforeUnmount(()=>{disposed=true;unregisterTaskDraft();window.removeEventListener('beforeunload',protectTaskPageExit);window.removeEventListener('keydown',detailEscape);window.removeEventListener('pointerdown',detailMoreOutside);window.removeEventListener(TASKS_BACKGROUND_REFRESH_EVENT,acceptBackgroundTasks);window.removeEventListener('online',refreshTaskLists)})
</script>

