<section class="task-center">
<header class="task-workspace-heading"><h1>{{taskScopeTitle}}</h1><p>共 {{filteredTasks.length}} 个任务</p></header>
  <div class="task-tabs"><div class="task-view-switch"><button :class="{active:view==='list'}" @click="view='list'"><span aria-hidden="true">☷</span> 列表</button><button :class="{active:view==='board'}" @click="view='board'">看板</button><button :class="{active:view==='calendar'}" @click="view='calendar'">日历</button></div><button v-if="!selectionMode" class="task-tab-create pc-action pc-action--primary" @click="newTask()">＋ 新建任务</button><div class="task-list-controls"><template v-if="!selectionMode"><select v-model="toolbarStatus" class="task-toolbar-select" aria-label="任务状态"><option value="">状态</option><option value="active">未完成</option><option value="completed">已完成</option><option value="all">全部进度</option></select><select v-model="toolbarPriority" class="task-toolbar-select" aria-label="任务优先级筛选"><option value="">优先级</option><option value="2">高优先级</option><option value="1">中优先级</option><option value="0">无优先级</option></select><select v-model="toolbarTag" class="task-toolbar-select" aria-label="任务标签筛选"><option value="">标签</option><option v-for="tag in tags" :key="tag.id" :value="String(tag.id)">{{tag.name}}</option></select></template><div v-if="selectionMode" class="task-selection-tools"><label><input type="checkbox" :disabled="bulkBusy||!selectableTaskRows.length" :checked="selectableTaskRows.length>0&&selectableTaskRows.every(task=>selected.has(task.uid))" :indeterminate="selectedCount>0&&!selectableTaskRows.every(task=>selected.has(task.uid))" @change="selectableTaskRows.forEach(task=>toggleSelection(task.uid,($event.target as HTMLInputElement).checked))"/>全选当前列表</label><span>已选 {{selectedCount}}</span><button :disabled="bulkBusy" @click="toggleSelectionMode">完成选择</button></div><details v-if="!selectionMode&&!projectScopeUid" class="task-view-more task-project-filter"><summary title="筛选任务">项目{{toolbarProject?' · 1':''}}</summary><div><header>所属项目</header><button :class="{active:!toolbarProject}" @click="toolbarProject='';($event.currentTarget as HTMLElement).closest('details')?.removeAttribute('open')"><span>全部项目</span><b>{{!toolbarProject?'✓':''}}</b></button><button v-for="project in projects.filter(item=>!['completed','archived'].includes(item.status))" :key="project.uid" :class="{active:toolbarProject===project.uid}" @click="toolbarProject=project.uid;($event.currentTarget as HTMLElement).closest('details')?.removeAttribute('open')"><span>{{project.name}}</span><b>{{toolbarProject===project.uid?'✓':''}}</b></button></div></details><label v-if="!selectionMode" class="task-sort-control"><span class="sort-label">排序</span><select v-model="sortMode" aria-label="任务排序"><option value="due">按日期</option><option value="priority">按优先级</option><option value="updated">按最近更新</option></select></label><details v-if="!selectionMode" class="task-view-more"><summary title="视图设置" class="pc-more-trigger" aria-label="视图设置"><MoreIcon/></summary><div><button v-if="view==='list'" aria-label="批量管理" @click="toggleSelectionMode"><span>批量管理</span><b>›</b></button><i v-if="view==='list'"/><header>显示密度</header><button v-for="item in ([['compact','简洁'],['comfortable','舒适'],['table','表格']] as const)" :key="item[0]" :class="{active:density===item[0]}" @click="changeDensity(item[0])"><span>{{item[1]}}</span><b>{{density===item[0]?'✓':''}}</b></button><i/><button @click="openActivity"><span>全部操作记录</span><b>›</b></button></div></details></div></div>
