e(task)):'未安排日期'}}{{taskBucket(task)==='overdue'?'（已逾期）':''}}</span></time><span v-if="task.completed" class="board-completed-time">✓ 已完成{{boardCompletedTime(task)?` ${boardCompletedTime(task)}`:''}}</span><em v-else-if="task.priority" :class="['priority',priorityLabel(task.priority)]">⚑ {{priorityLabel(task.priority)}}</em><button class="board-card-menu pc-more-trigger pc-action pc-action--secondary" :aria-label="`任务操作 ${task.title}`" @click.stop="taskContextMenu(task,$event)"><MoreIcon/></button></footer></article></div><button class="board-column-add" @click="newBoardTask(column.key)">＋ 添加任务</button></section></div></section>
  <div v-else class="task-calendar-workspace"><div class="task-calendar"><header class="task-month-toolbar"><div><button aria-label="上个月" @click="changeMonth(-1)">‹</button><strong>{{calendarTitle}}</strong><button aria-label="下个月" @click="changeMonth(1)">›</button><button @click="calendarAnchor=new Date(new Date().getFullYear(),new Date().getMonth(),1);selectedCalendarDay=todayKey">今天</button></div><label class="calendar-repeat-toggle"><input v-model="showFutureRecurrences" type="checkbox"/>显示重复任务</label><span class="calendar-view-label">月视图</span></header><div class="calendar-week"><span v-for="day in ['一','二','三','四','五','六','日']" :key="day">周{{day}}</span></div><div class="calendar-grid" :style="{'--calendar-rows':calendarDays.length/7}"><section v-for="day in calendarDays" :key="day.key" :aria-label="day.key" :class="{muted:!day.current,today:day.today,selected:selectedCalendarDay===day.key}" @click="selectedCalendarDay=day.key" @dblclick="newTask(day.date)" @dragover.prevent @drop.stop="dropOnDate($event,day.key)"><header><time>{{day.date.getDate()}}</time><span v-if="day.holiday" class="calendar-holiday" :class="day.holiday.kind" :title="day.holiday.label">{{day.holiday.kind==='workday'?'班':day.date.getDate()===1?day.holiday.label:'休'}}</span></header><button v-for="task in day.tasks.slice(0,2)" :key="task.uid" :draggable="!task.recurrencePreview" :class="{done:task.completed,active:selectedTaskUid===task.uid,deadline:Boolean(task.dueAt)}" @dragstart="!task.recurrencePreview&&startTaskDrag($event,task)" @click.stop="openCalendarTask(task)"><i :class="{repeat:Boolean(task.recurrenceRule)}"/><span>{{task.title}}</span></button><button v-if="day.tasks.length>2" class="calendar-more-count" @click.stop="selectedCalendarDay=day.key">＋ {{day.tasks.length-2}} 项</button></section></div><details class="calendar-source-info"><summary>节假日数据说明</summary><p class="calendar-holiday-source">中国大陆 · <a v-if="calendarAnchor.getFullYear()===holidaySource.year" :href="holidaySource.url" target="_blank" rel="noopener noreferrer">{{holidaySource.title}}</a><span v-else>本年度放假调休数据尚未收录</span> · 休：假期，班：调休上班</p></details></div><aside class="calendar-agenda"><header><div><strong>{{calendarSelectedLabel}}</strong><small>农历{{calendarSelectedLunar}}</small></div><nav><button aria-label="前一天" @click="shiftCalendarDay(-1)">‹</button><button aria-label="后一天" @click="shiftCalendarDay(1)">›</button></nav></header><button class="calendar-day-create" @click="newTask(calendarSelectedDate)">＋ 新建任务</button><div class="calendar-agenda-list"><section v-for="group in [{label:'当日任务',items:calendarPendingTasks,done:false},{label:'已完成',items:calendarCompletedTasks,done:true}]" :key="group.label" class="calendar-day-group"><h3>{{group.label}} <small>{{group.items.length}}</small></h3><p v-if="!group.items.length" class="calendar-day-empty">{{group.done?'当天还没有已完成任务':'当天没有待办任务'}}</p><article v-for="task in group.items" :key="task.uid" :class="{done:task.completed}"><input type="checkbox" :checked="task.completed" :disabled="task.recurrencePreview" :aria-label="`完成日历任务 ${task.title}`" @change="!task.recurrencePreview&&completeTask(task,($event.target as HTMLInputElement).checked)"/><div><button class="calendar-day-task-title" @click="openCalendarTask(task)">{{task.title}}</button><div class="calendar-day-task-meta"><span v-if="task.recurrenceRule">↻ {{task.recurrencePreview?'周期预览':recurrenceLabel(task.recurrenceRule)}}</span><time>{{formatDate(effectiveDate(task))}}</time></div><div class="calendar-day-tags"><span v-if="taskProjectLabel(task)">{{taskProjectLabel(task)}}</span><span v-for="tag in taskRowTags(task)" :key="tag.id">{{tag.name}}</span></div></div></article></section><section class="calendar-unscheduled" @dragover.prevent @drop="dropOnDate($event,null)"><header><strong>待安排</strong><small>{{unscheduledTasks.length}}</small></header><p v-if="!unscheduledTasks.length">暂无其他待安排任务</p><button v-for="task in unscheduledTasks.slice(0,5)" :key="task.uid" draggable="true" @dragstart="startTaskDrag($event,task)" @click="openCalendarTask(task)"><span>{{task.title}}</span><b>⠿</b></button><small v-if="unscheduledTasks.length>5">另有 {{unscheduledTasks.length-5}} 项</small></section></div></aside></div>
  </div></Transition></div>
  <div v-if="selectedCount||bulkUndo" class="bulk-actions"><strong v-if="selectedCount">已选择 {{selectedCount}} 项</strong><button v-if="selectedCount" @click="openTaskBulk('move')">移动</button><button v-if="selectedCount" @click="openTaskBulk('date')">日期</button><button v-if="selectedCount" @click="openTaskBulk('complete')">标记完成</button><details v-if="selectedCount"><summary class="pc-more-trigger" aria-label="更多操作" title="更多操作"><MoreIcon/></summary><div><button @click="openTaskBulk('tag')">添加标签</button><button @click="openTaskBulk('priority')">设置优先级</button><button @click="openTaskBulk('copy')">复制</button><button class="danger-text" @click="openTaskBulk('delete')">删除</button></div></details><button v-if="bulkUndo" :disabled="bulkBusy" @click="undoTaskBulk">撤销</button><button v-if="selectedCount" @click="selected=new Set()">取消选择</button></div>
  <Teleport to="body"><div v-if="bulkAction&&bulkAction!=='delete'" class="pc-modal-backdrop" @click.self="!bulkBusy&&(bulkAction=undefined)"><section ref="bulkPanel" tabindex="-1" role="dialog" aria-label="批量任务操作" aria-modal="true" class="pc-task-dialog bulk-dialog" @keydown="dialogKey($event,()=>bulkAction=undefined,bulkBusy)"><fieldset class="bulk-dialog-fields" :disabled="bulkBusy"><div class="section-heading"><div><h2>批量{{({move:'移动',tag:'标签',complete:'完成',date:'日期',priority:'优先级',copy:'复制'} as Record<string,string>)[bulkAction]}}</h2><p>将处理 {{bulkItems.length}} 个任务，失败项会保留选择。</p></div><button aria-label="关闭批量操作" @click="bulkAction=undefined">×</button></div><template v-if="bulkAction==='move'"><label>移动到<select v-model="bulkDestination"><option value="inbox">收集箱</option><option value="list">清单</option><option value="project">领域 / 项目</option></select></label><label v-if="bulkDestination==='list'">目标清单<select v-model="bulkTaskListUid"><option disabled value="">请选择清单</option><option v-for="item in taskLists" :key="item.uid" :value="item.uid">{{item.name}} {{areas.find(area=>area.uid===item.areaUid)?.name}}</option></select></label><template v-if="bulkDestination==='project'"><label>目标领域<select v-model="bulkAreaUid" @change="bulkProjectUid=''"><option disabled value="">请选择领域</option><option v-for="area in areas" :key="area.uid" :value="area.uid">{{area.name}}</option></select></label><label>目标项目<select v-model="bulkProjectUid"><option value="">不归属项目</option><option v-for="item in bulkTargetProjects" :key="item.uid" :value="item.uid">{{item.name}}</option></select></label></template></template><label v-else-if="bulkAction==='tag'">添加标签<select v-model.number="bulkTagId"><option v-for="tag in tags" :key="tag.id" :value="tag.id">{{tag.name}}</option></select></label><label v-else-if="bulkAction==='date'">任务日期<PcDatePicker v-model="bulkDate" include-time aria-label="选择批量任务日期" placeholder="选择任务日期"/></label><label v-else-if="bulkAction==='priority'">优先级<select v-model.number="bulkPriority"><option :value="0">无</option><option :value="1">中</option><option :value="2">高</option></select></label><p v-else>{{bulkAction==='copy'?'为所选任务创建副本，重试仅处理失败项。':'仅完成当前未完成的任务。'}}</p><div v-if="bulkFailures.length" class="bulk-failures" role="alert"><strong>{{bulkFailures.length}} 项失败</strong><span v-for="failure in bulkFailures" :key="failure.item.uid">{{failure.item.title}}：{{failure.message}}</span></div><div class="dialog-actions"><button class="pc-action pc-action--secondary" @click="bulkAction=undefined">取消</button><button class="primary-action pc-action pc-action--primary" :disabled="bulkBusy" @click="executeTaskBulk">{{bulkBusy?'处理中…':'确认执行'}}</button></div></fieldset></section></div></Teleport>
  <div v-if="activityOpen" class="pc-modal-backdrop" @click.self="closeActivity"><section ref="activityPanel" tabindex="-1" role="dialog" aria-modal="true" aria-labelledby="task-activity-title" class="pc-task-dialog task-activity-dialog" @keydown="dialogKey($event,closeActivity,false)"><div class="section-heading"><div><h2 id="task-activity-title">任务操作记录</h2><p>最近的创建、更新和删除记录</p></div><button aria-label="关闭操作记录" @click="closeActivity">×</button></div><div class="task-activity"><p v-if="activityLoading">正在加载…</p><p v-else-if="activityError" class="task-activity-error" role="alert">{{activityError}} <button @click="loadActivity">重试</button></p><p v-else-if="!activity.length">还没有操作记录。</p><article v-for="item in activity" :key="item.seq"><i :class="item.action"/><div><strong>{{activityLabel(item)}}</strong><p>{{item.entity?.title||'已删除任务'}}</p></div><time>{{new Date(item.changedAt).toLocaleString('zh-CN')}}</time></article></div></section></div>
  <div v-if="notePickerOpen" class="pc-modal-backdrop" @click.self="notePickerOpen=false"><section class="pc-task-dialog task-note-picker-dialog"><div class="section-heading"><div><h2>关联笔记</h2><p>搜索或从最近笔记中选择</p></div><button @click="notePickerOpen=false">×</button></div><input v-model="noteQuery" autofocus placeholder="搜索笔记标题或内容"/><div class="pc-note-picker-results"><button v-for="note in noteCandidates" :key="note.uid" :disabled="linkedNoteUids.has(note.uid)" @click="selectExistingNote(note)"><span>▤</span><div><strong>{{note.title||'无标题笔记'}}</strong><small>{{notePickerContext(note)}}</small></div><b>{{linkedNoteUids.has(note.uid)?'已关联':'关联'}}</b></button><p v-if="!noteCandidates.length">没有匹配的笔记</p></div></section></div>
  <Teleport to="body"><div v-if="textDialog" class="pc-modal-backdrop" @click.self="!textDialogBusy&&(textDialog=null)"><form ref="textPanel" tabindex="-1" role="dialog" aria-modal="true" :aria-label="textDialog.title" class="pc-task-dialog task-text-dialog" @keydown="dialogKey($event,()=>textDialog=null,textDialogBusy)" @submit.prevent="submitTextDialog"><div class="section-heading"><div><h2>{{textDialog.title}}</h2><p>输入后即可保存</p></div><button type="button" :disabled="textDialogBusy" @click="textDialog=null">×</button></div><label>{{textDialog.label}}<input v-model="textDialog.value" autofocus maxlength="120"/></label><p v-if="textDialogError" class="task-dialog-error" role="alert">{{textDialogError}}</p><div class="dialog-actions"><button class="pc-action pc-action--secondary" type="button" :disabled="textDialogBusy" @click="textDialog=null">取消</button><button class="primary-action pc-action pc-action--primary" :disabled="textDialogBusy||!textDialog.value.trim()">{{textDialogBusy?'保存中…':'保存'}}</button></div></form></div></Teleport>
</section>

<ElDialog :model-value="Boolean(selectedTask)&&!productDialogState.open&&!textDialog&&!notePickerOpen&&taskAttachmentPreviewIndex<0" title="任务详情与编辑" class="task-detail-dialog" width="min(860px, calc(100vw - 40px))" align-center :z-index="100" :show-close="false" :before-close="beforeDetailClose" :close-on-click-modal="false" append-to-body>
<TaskDetailContent v-if="selectedTask" :task="selectedTask" :lists="taskLists" :projects="projects" :tags="tags" :children="selectedChildren" :related-count="referenceNotes.length" :activity-count="selectedActivity.length" :saving="detailSaving" :error="detailError" :save="saveTaskDetails" @close="closeDetail" @more="openTaskDetailsMenu" @complete="completeTask(selectedTask,$event)" @draft-change="value=>{taskDialogDirty=value;if(!value)detailError=''}" @draft-stamp="taskDialogStamp=$event" @begin-edit="beginTaskDetailsEdit" @activity-open="loadActivity" @add-child="addSubtask" @toggle-child="toggleChild" @open-child="editTask" @move-child="moveChild">
 <template #related>    <section class="task-workbench-block task-inline-links"><header><button class="task-section-add pc-action pc-action--text" @click="linkExistingNote">＋ 关联笔记</button><button class="task-section-add pc-action pc-action--text" @click="createLinkedNote">新建关联笔记</button></header><article v-for="item in referenceNotes" :key="item.relation.uid"><span>🔗</span><b @click="openNote(item.note?.uid)">{{item.note?.title||'尚未同步的笔记'}}</b><button @click="unlinkNote(item.relation)">解除</button></article><details v-if="pendingTaskNotes.length" class="task-note-pending"><summary>{{pendingTaskNotes.length}} 条关联操作待确认</summary><p>未确认的操作会保留在本机，联网后可重试。</p><div v-for="item in pendingTaskNotes" :key="item.uid"><span>{{item.action==='create'?'关联待上传':'解绑待确认'}} · {{notesStore.notes.find(note=>note.uid===item.noteUid)?.title||'笔记'}}</span><button v-if="item.action==='delete'" @click="stopUnlinkRetry(item)">停止重试</button></div><button :disabled="relatedLoading" @click="loadRelated">重试</button></details><p v-if="!referenceNotes.length" class="task-inline-empty">暂无关联内容</p></section>
    <section v-if="knowledgeAvailable&&taskKnowledge.length" class="task-workbench-block task-knowledge-block"><header><strong>参考知识 <small>{{taskKnowledge.length}}</small></strong><button @click="openField('knowledge')">＋ 继续关联</button></header><article v-for="item in taskKnowledge" :key="item.uid"><span>◇</span><div><b @click="openKnowledge(item.knowledgeUid)">{{item.title||'知识'}}</b><small>{{item.conclusion||item.feedback||'已引用到当前任务'}}</small></div><template v-if="selectedTask.completed"><button :disabled="knowledgeBusy" @click="feedbackKnowledge(item,'validated')">有效</button><button :disabled="knowledgeBusy" @click="feedbackKnowledge(item,'challenged')">需修订</button></template></article></section>
    <section v-if="taskAttachments.length||taskPendingRemovals.length" class="task-workbench-block"><p v-if="taskPendingRemovals.length" role="status" class="task-removal-notice">{{taskUnknownRemovals?'部分附件上传结果未知，远程移除尚未确认。':`${taskPendingRemovals.length} 个附件已在本机移除，等待远程确认。`}}<button :disabled="attachmentBusy" @click="retryTaskRemovals">重试确认</button></p><header><strong>附件</strong><small>{{taskAttachments.length}}</small></header><article v-for="item in taskAttachments" :key="item.uid"><span>📎</span><button class="task-attachment-open" @click="openTaskFile(item)">{{item.originalFilename}}</button><small>{{Math.max(1,Math.round(item.sizeBytes/1024))}} KB</small><button :disabled="attachmentBusy" @click="detachTaskFile(item)">移除</button></article><label class="block-add">＋ 添加附件<input type="file" multiple @change="addTaskFiles"/></label></section>
</template>
 <template #activity>  <section class="task-detail-activity"><p v-if="activityLoading">正在加载活动…</p><p v-else-if="activityError" class="task-activity-error" role="alert">{{activityError}} <button @click="loadActivity">重试</button></p><p v-else-if="!selectedActivity.length">还没有与这个任务相关的活动。</p><article v-for="item in selectedActivity" :key="item.seq"><i/><div><strong>{{activityLabel(item)}}</strong><time>{{new Date(item.changedAt).toLocaleString('zh-CN')}}</time></div></article></section>
</template>
 <template #source><dl class="task-concept-source"><div><dt>任务 ID</dt><dd>{{selectedTask.uid}}</dd></div><div><dt>创建时间</dt><dd>{{formatFullDate(selectedTask.createdAt)}}</dd></div><div><dt>更新时间</dt><dd>{{formatFullDate(selectedTask.updatedAt)}}</dd></div><div><dt>来源</dt><dd>{{sourceNotes[0]?.note?.title||'当前任务'}}</dd></div></dl>
</template>
</TaskDetailContent>
<template v-if="selectedTask">
    <button v-if="detailField&&detailField!=='title'&&detailField!=='description'" class="task-popover-scrim" aria-label="关闭属性面板" @click="cancelField"/>
    <div v-if="detailField&&detailField!=='title'&&detailField!=='description'" class="task-field-popover" role="dialog" aria-labelledby="task-field-heading" :class="[`field-${detailField}`,`placement-${popoverPlacement}`]" :style="detailPopoverStyle">
      <header><strong id="task-field-heading">{{({time:'时间安排',date:'任务日期',due:'截止时间',reminder:'提醒',recurrence:'重复',duration:'预计时长',priority:'优先级',project:'移动任务',tags:'添加标签',knowledge:'关联知识'} as Record<string,string>)[detailField]}}</strong><button aria-label="关闭属性面板" @click="cancelField">×</button></header><p v-if="detailError" class="task-property-error" role="alert">{{detailError}}</p>
      <template v-if="detailField==='time'||detailField==='date'||detailField==='due'">
        <div v-if="detailField==='time'" class="time-target-tabs"><button :class="{active:timeTarget==='date'}" @click="switchTimeTarget('date')">计划时间<small>{{formatFullDate(selectedTask.startAt)}}</small></button><button :class="{active:timeTarget==='due'}" @click="switchTimeTarget('due')">截止时间<small>{{formatFullDate(selectedTask.dueAt)}}</small></button></div>
        <div class="deadline-presets"><button @click="chooseTaskDate('today')"><b>今天</b><small>{{timeTarget==='date'?'09:00':'18:00'}}</small></button><button @click="chooseTaskDate('tomorrow')"><b>明天</b><small>{{timeTarget==='date'?'09:00':'18:00'}}</small></button><button @click="chooseTaskDate('friday')"><b>本周五</b><small>{{timeTarget==='date'?'09:00':'18:00'}}</small></button><button @click="chooseTaskDate('monday')"><b>下周一</b><small>{{timeTarget==='date'?'09:00':'18:00'}}</small></button></div>
        <div class="deadline-custom"><label><span>日期</span><PcDatePicker v-model="deadlineDate" aria-label="选择任务日期"/></label><label><span>时间</span><input v-model="deadlineTime" type="time"/></label></div>
        <footer><button class="danger-text pc-action pc-action--danger" @click="deadlineDate='';saveCustomTaskDate()">清除{{timeTarget==='date'?'日期':'截止'}}</button><i/><button class="pc-action pc-action--secondary" @click="cancelField">取消</button><button class="primary-action pc-action pc-action--primary" @click="saveCustomTaskDate">完成</button></footer>
      </template>
      <div v-else-if="detailField==='reminder'" class="quick-property-list reminder-quick-list"><p v-if="!selectedTask.startAt&&!selectedTask.dueAt">设置提醒前，请先设置日期或截止时间。</p><button v-for="item in [{value:0,label:'准时'},{value:10,label:'提前 10 分钟'},{value:30,label:'提前 30 分钟'},{value:60,label:'提前 1 小时'},{value:1440,label:'提前 1 天'}]" :key="item.value" :class="{selected:selectedTask.reminderOffsetsMinutes?.includes(item.value)}" :disabled="detailSaving||(!selectedTask.startAt&&!selectedTask.dueAt)" @click="toggleReminder(item.value)"><span>{{item.label}}</span><b>{{selectedTask.reminderOffsetsMinutes?.includes(item.value)?'✓':''}}</b></button><label><input v-model.number="reminderAmount" type="number" min="1"/><select v-model.number="reminderUnit"><option :value="1">分钟</option><option :value="60">小时</option><option :value="1440">天</option></select><button :disabled="detailSaving||(!selectedTask.startAt&&!selectedTask.dueAt)" @click="addCustomReminder">添加</button></label><small>可同时设置多个提醒，点击选项即可切换</small></div>
      <TaskRepeatEditor v-else-if="detailField==='recurrence'" :rule="selectedTask.recurrenceRule" :saving="detailSaving" :error="detailError" @save="saveRepeatRule"/>
      <div v-else-if="detailField==='duration'" class="quick-property-list duration-quick-list"><button v-for="minutes in [15,30,60,120]" :key="minutes" :class="{selected:selectedTask.estimatedMinutes===minutes}" @click="saveField({estimatedMinutes:minutes})"><span>{{durationLabel(minutes)}}</span><b>{{selectedTask.estimatedMinutes===minutes?'✓':''}}</b></button><label><input v-model.number="durationMinutes" type="number" min="1" max="10080"/><span>分钟</span><button @click="saveDuration">应用</button></label><button class="duration-clear" @click="saveField({estimatedMinutes:null})"><span>清除预计时长</span><b/></button></div>
      <div v-else-if="detailField==='priority'" class="task-choice-list"><button v-for="item in [{v:2,l:'高'},{v:1,l:'中'},{v:0,l:'无'}]" :key="item.v" @click="saveField({priority:item.v})">⚑ {{item.l}}</button></div>
      <div v-else-if="detailField==='project'" class="task-choice-list task-location-choices"><button :disabled="detailSaving" @click="selectProject('')">收集箱</button><h4>清单</h4><button v-for="item in taskLists" :key="`list:${item.uid}`" :disabled="detailSaving" @click="selectTaskList(item)">{{item.name}}<small>{{areas.find(area=>area.uid===item.areaUid)?.name}}</small><span v-if="selectedTask.taskListUid===item.uid">✓</span></button><p v-if="!taskLists.length">暂无清单，可在左侧创建</p><h4>项目</h4><button v-for="item in projects.filter(value=>!['completed','archived'].includes(value.status))" :key="`project:${item.uid}`" :disabled="detailSaving" @click="selectProject(item.uid)">{{item.name}}</button></div>
      <template v-else-if="detailField==='tags'"><label class="task-tag-search">⌕<input v-model="tagQuery" autofocus placeholder="搜索或新建标签" @keydown.enter.prevent="createDetailTag"/></label><div class="task-tag-choices"><button v-for="tag in filteredDetailTags" :key="tag.id" :class="{selected:selectedTask.tagIds?.includes(tag.id)}" :disabled="detailSaving" @click="toggleTagImmediately(tag.id)"><i :style="{background:tag.color||'#7a9d86'}"/><span># {{tag.name}}</span><b>{{selectedTask.tagIds?.includes(tag.id)?'✓':''}}</b></button><p v-if="!filteredDetailTags.length">没有匹配标签</p></div><button v-if="tagQuery.trim()&&!tags.some(item=>item.name.toLowerCase()===tagQuery.trim().toLowerCase())" class="task-tag-create" :disabled="detailSaving" @click="createDetailTag">＋ 新建“{{tagQuery.trim()}}”</button><small class="task-popover-hint">点击即可切换，修改会立即保存</small></template>
      <div v-else-if="detailField==='knowledge'" class="task-knowledge-picker"><select v-model="knowledgeChoice" autofocus><option value="">选择要关联的知识</option><option v-for="item in availableKnowledge" :key="item.uid" :value="item.uid">{{item.title}}</option></select><p v-if="!availableKnowledge.length">没有可关联的知识。</p><button :disabled="!knowledgeChoice||knowledgeBusy" @click="attachKnowledge">{{knowledgeBusy?'关联中…':'确认关联'}}</button></div>
      <footer v-if="!['priority','project','time','date','due','reminder','recurrence','duration','tags','knowledge'].includes(detailField)"><button class="pc-action pc-action--secondary" @click="cancelField">取消</button><button class="primary-action pc-action pc-action--primary" @click="saveField()">保存</button></footer>
    </div>
</template>
</ElDialog>
<AttachmentPreviewDialog v-if="taskAttachmentPreviewIndex>=0&&selectedTask" :owner-id="attachmentOwnerId" :items="taskAttachments" :index="taskAttachmentPreviewIndex" @change="taskAttachmentPreviewIndex=$event" @close="taskAttachmentPreviewIndex=-1"/>
<aside v-if="projectLogOffer" class="task-log-offer"><div><strong>任务已完成</strong><span>要把结果记录到项目日志吗？</span></div><button @click="projectLogOffer=undefined">忽略</button><button class="primary-action pc-action pc-action--primary" :disabled="projectLogBusy" @click="recordCompletionLog">{{projectLogBusy?'记录中…':'记录'}}</button></aside>
